-- ================================================================================================
-- L3a · GeoAreaKey -> one StateFull / State / Country / CountryFull / Continent? (keys with more than one distinct value on the right)
-- ================================================================================================
SELECT count(*) FILTER (WHERE d_statefull > 1) AS geoarea_with_2_statefull, count(*) FILTER (WHERE d_state > 1) AS with_2_state, count(*) FILTER (WHERE d_country > 1) AS with_2_country, count(*) FILTER (WHERE d_countryfull > 1) AS with_2_countryfull, count(*) FILTER (WHERE d_continent > 1) AS with_2_continent, count(*) AS geoareas FROM (SELECT "GeoAreaKey", count(DISTINCT "StateFull") d_statefull, count(DISTINCT "State") d_state, count(DISTINCT "Country") d_country, count(DISTINCT "CountryFull") d_countryfull, count(DISTINCT "Continent") d_continent FROM contoso_served.dim_contoso_customer GROUP BY 1);
-- ANSWER:
-- 0   0   0   0   0   608

-- ================================================================================================
-- L3b · Country -> one CountryFull and one Continent?
-- ================================================================================================
SELECT count(*) AS countries, count(*) FILTER (WHERE d_full > 1) AS with_2_names, count(*) FILTER (WHERE d_cont > 1) AS with_2_continents FROM (SELECT "Country", count(DISTINCT "CountryFull") d_full, count(DISTINCT "Continent") d_cont FROM contoso_served.dim_contoso_customer GROUP BY 1);
-- ANSWER:
-- 8   0   0

-- ================================================================================================
-- L3c · CategoryKey -> one CategoryName, SubCategoryKey -> one SubCategoryName and one parent CategoryKey?
-- ================================================================================================
SELECT (SELECT count(*) FROM (SELECT "CategoryKey" FROM contoso_served.dim_contoso_product GROUP BY 1 HAVING count(DISTINCT "CategoryName") > 1)) AS cat_with_2_names, (SELECT count(*) FROM (SELECT "SubCategoryKey" FROM contoso_served.dim_contoso_product GROUP BY 1 HAVING count(DISTINCT "SubCategoryName") > 1)) AS sub_with_2_names, (SELECT count(*) FROM (SELECT "SubCategoryKey" FROM contoso_served.dim_contoso_product GROUP BY 1 HAVING count(DISTINCT "CategoryKey") > 1)) AS sub_with_2_parents;
-- ANSWER:
-- 0   0   0

-- ================================================================================================
-- L3d · Brand <-> Manufacturer: is either direction a function today?
-- ================================================================================================
SELECT (SELECT count(*) FROM (SELECT "Brand" FROM contoso_served.dim_contoso_product GROUP BY 1 HAVING count(DISTINCT "Manufacturer") > 1)) AS brand_with_2_manufacturers, (SELECT count(*) FROM (SELECT "Manufacturer" FROM contoso_served.dim_contoso_product GROUP BY 1 HAVING count(DISTINCT "Brand") > 1)) AS manufacturer_with_2_brands;
-- ANSWER:
-- 0   0

-- ================================================================================================
-- L3e · MonthNumber -> one Month/MonthShort/Quarter; DayofWeekNumber -> one DayofWeek/DayofWeekShort
-- ================================================================================================
SELECT (SELECT count(*) FROM (SELECT "MonthNumber" FROM contoso_served.dim_contoso_calendar_day GROUP BY 1 HAVING count(DISTINCT "Month") > 1 OR count(DISTINCT "MonthShort") > 1 OR count(DISTINCT "Quarter") > 1)) AS month_ambiguous, (SELECT count(*) FROM (SELECT "DayofWeekNumber" FROM contoso_served.dim_contoso_calendar_day GROUP BY 1 HAVING count(DISTINCT "DayofWeek") > 1 OR count(DISTINCT "DayofWeekShort") > 1)) AS weekday_ambiguous;
-- ANSWER:
-- 0   0

