-- L4 · cut contoso_brand.lookup.csv from dim_contoso_product
-- ================================================================================================
SELECT "Brand" AS "Brand", "Brand" AS label, lower(trim("Brand")) AS search_key,
       "Manufacturer" AS manufacturer, 'dim_contoso_product' AS source_view, 'I' AS confidence,
       'value set measured on ' || count(*) || ' of 2517 served product rows' AS note
