-- ================================================================================================
-- L4 · cut contoso_currency.lookup.csv from v_contoso_order_line
-- ================================================================================================
-- Cut from the FACT, not from the FX relation: `CurrencyCode` is how the served fact spells
-- this code, and a register's code column must be spelled as the dataset it joins to spells it.
-- The FX relation spells the same codes `FromCurrency`/`ToCurrency`, and L7a measures the three
-- sets identical (5 of 5, 0 either way), so the choice of source loses no code.
SELECT "CurrencyCode" AS "CurrencyCode", '' AS label, '' AS search_key,
       'v_contoso_order_line' AS source_view, 'Q' AS confidence,
       'code measured on ' || count(*) || ' served order lines; no currency NAME exists anywhere in '
       'the delivery (L6d/L6d2), so the label is deliberately empty rather than recalled from '
       'outside the data' AS note
FROM contoso_served.v_contoso_order_line
GROUP BY "CurrencyCode"
ORDER BY "CurrencyCode";
-- ANSWER:
-- AUD         v_contoso_order_line   Q   code measured on 14078 served order lines; no currency NAME exists anywhere in the delivery (L6d/L6d2), so the label is deliberately empty rather than recalled from outside the data
-- CAD         v_contoso_order_line   Q   code measured on 24250 served order lines; no currency NAME exists anywhere in the delivery (L6d/L6d2), so the label is deliberately empty rather than recalled from outside the data
-- EUR         v_contoso_order_line   Q   code measured on 49203 served order lines; no currency NAME exists anywhere in the delivery (L6d/L6d2), so the label is deliberately empty rather than recalled from outside the data
-- GBP         v_contoso_order_line   Q   code measured on 22829 served order lines; no currency NAME exists anywhere in the delivery (L6d/L6d2), so the label is deliberately empty rather than recalled from outside the data
-- USD         v_contoso_order_line   Q   code measured on 113614 served order lines; no currency NAME exists anywhere in the delivery (L6d/L6d2), so the label is deliberately empty rather than recalled from outside the data

-- ================================================================================================
-- L4 · cut contoso_country.lookup.csv from dim_contoso_customer
-- ================================================================================================
-- 8 rows from the customer dimension (the only served relation carrying a continent) plus
-- the store dimension's sentinel, which is a country code in shape only.
SELECT "Country" AS "Country", "CountryFull" AS label, lower(trim("CountryFull")) AS search_key,
       "Continent" AS continent, 'dim_contoso_customer' AS source_view, 'I' AS confidence,
       'served customers in this country: ' || count(*) AS note
FROM contoso_served.dim_contoso_customer
GROUP BY "Country", "CountryFull", "Continent"
UNION ALL
SELECT "CountryCode", "CountryName", lower(trim("CountryName")), '',
       'dim_contoso_store', 'Q',
       'SENTINEL, not a country: the online store version carries CountryCode ''--'' and '
       'CountryName/State ''Online''. Kept so a store row always resolves; its continent is empty '
       'because the data states none. Whether ''--'' means ''no geography'' or ''global'' is an open '
       'ruling'
FROM contoso_served.dim_contoso_store
WHERE "CountryCode" NOT IN (SELECT "Country" FROM contoso_served.dim_contoso_customer)
GROUP BY "CountryCode", "CountryName"
ORDER BY 1;
