SELECT "Quarter" AS "Quarter", "Quarter" AS label, lower(trim("Quarter")) AS search_key,
       'dim_contoso_calendar_day' AS source_view, 'I' AS confidence,
       'member months: ' || list_aggregate(list_sort(list(DISTINCT "MonthNumber")), 'string_agg', '+')
       AS note
FROM contoso_served.dim_contoso_calendar_day
GROUP BY "Quarter"
ORDER BY "Quarter";
-- ANSWER:
-- Q1   Q1   q1   dim_contoso_calendar_day   I   member months: 1+2+3
-- Q2   Q2   q2   dim_contoso_calendar_day   I   member months: 4+5+6
-- Q3   Q3   q3   dim_contoso_calendar_day   I   member months: 7+8+9
-- Q4   Q4   q4   dim_contoso_calendar_day   I   member months: 10+11+12

-- ================================================================================================
-- L4 · cut contoso_calendar_weekday.lookup.csv from dim_contoso_calendar_day
-- ================================================================================================
SELECT "DayofWeekNumber" AS "DayofWeekNumber", "DayofWeek" AS label,
       lower(trim("DayofWeek")) AS search_key, "DayofWeekShort" AS label_short,
       lower(trim("DayofWeekShort")) AS search_key_short, 'dim_contoso_calendar_day' AS source_view, 'I' AS confidence,
       'calendar days: ' || count(*) || '; working days among them: '
       || count(*) FILTER (WHERE "WorkingDay" = 1) AS note
FROM contoso_served.dim_contoso_calendar_day
GROUP BY "DayofWeekNumber", "DayofWeek", "DayofWeekShort"
ORDER BY "DayofWeekNumber";
-- ANSWER:
-- 1   Sunday   sunday   Sun   sun   dim_contoso_calendar_day   I   calendar days: 574; working days among them: 0
-- 2   Monday   monday   Mon   mon   dim_contoso_calendar_day   I   calendar days: 574; working days among them: 505
-- 3   Tuesday   tuesday   Tue   tue   dim_contoso_calendar_day   I   calendar days: 574; working days among them: 569
-- 4   Wednesday   wednesday   Wed   wed   dim_contoso_calendar_day   I   calendar days: 574; working days among them: 567
-- 5   Thursday   thursday   Thu   thu   dim_contoso_calendar_day   I   calendar days: 574; working days among them: 558
-- 6   Friday   friday   Fri   fri   dim_contoso_calendar_day   I   calendar days: 574; working days among them: 561
-- 7   Saturday   saturday   Sat   sat   dim_contoso_calendar_day   I   calendar days: 574; working days among them: 0

-- ================================================================================================
-- L4 · cut contoso_working_day.lookup.csv from dim_contoso_calendar_day
-- ================================================================================================
SELECT "WorkingDay" AS "WorkingDay",
       CASE "WorkingDay" WHEN 1 THEN 'working day' ELSE 'non-working day' END AS label,
       CASE "WorkingDay" WHEN 1 THEN 'working day' ELSE 'non-working day' END AS search_key,
       'dim_contoso_calendar_day' AS source_view, 'I' AS confidence,
       'calendar days: ' || count(*) || '; of them on Sat/Sun: '
       || count(*) FILTER (WHERE "DayofWeekNumber" IN (1, 7)) AS note
FROM contoso_served.dim_contoso_calendar_day
GROUP BY "WorkingDay"
ORDER BY "WorkingDay" DESC;
-- ANSWER:
-- 1   working day   working day   dim_contoso_calendar_day   I   calendar days: 2760; of them on Sat/Sun: 0
-- 0   non-working day   non-working day   dim_contoso_calendar_day   I   calendar days: 1258; of them on Sat/Sun: 1148

-- ================================================================================================
-- L6a · the region abbreviation is NOT an identity: how many GeoAreaKeys share a `State` abbreviation with another area?
-- ================================================================================================
SELECT count(DISTINCT "State") AS abbreviations, count(DISTINCT "GeoAreaKey") AS areas, (SELECT count(*) FROM (SELECT "State" FROM contoso_served.dim_contoso_customer GROUP BY 1 HAVING count(DISTINCT "GeoAreaKey") > 1)) AS abbreviations_used_by_2plus_areas, (SELECT sum(n) FROM (SELECT count(DISTINCT "GeoAreaKey") n FROM contoso_served.dim_contoso_customer GROUP BY "State" HAVING count(DISTINCT "GeoAreaKey") > 1)) AS areas_sharing_an_abbreviation FROM contoso_served.dim_contoso_customer;
-- ANSWER:
-- 563   608   40   85

-- ================================================================================================
-- L6b · the store code is NOT an identity: StoreCodes carried by more than one StoreKey
-- ================================================================================================
SELECT count(*) AS store_versions, count(DISTINCT "StoreCode") AS store_codes, (SELECT count(*) FROM (SELECT "StoreCode" FROM contoso_served.dim_contoso_store GROUP BY 1 HAVING count(*) > 1)) AS codes_with_2plus_versions FROM contoso_served.dim_contoso_store;
-- ANSWER:
-- 74   67   6

-- ================================================================================================
-- L6c · label collisions ACROSS registers: is any continent value also a country label, and is any category name also a subcategory name?
-- ================================================================================================
SELECT (SELECT count(*) FROM (SELECT DISTINCT "Continent" c FROM contoso_served.dim_contoso_customer) x JOIN (SELECT DISTINCT "CountryFull" c FROM contoso_served.dim_contoso_customer) y ON x.c = y.c) AS continent_words_that_are_also_country_words, (SELECT list(c) FROM (SELECT DISTINCT "Continent" c FROM contoso_served.dim_contoso_customer INTERSECT SELECT DISTINCT "CountryFull" FROM contoso_served.dim_contoso_customer)) AS which, (SELECT count(*) FROM (SELECT DISTINCT "CategoryName" c FROM contoso_served.dim_contoso_product INTERSECT SELECT DISTINCT "SubCategoryName" FROM contoso_served.dim_contoso_product)) AS category_words_that_are_also_subcategory_words;
-- ANSWER:
-- 1   ['Australia']   0

-- ================================================================================================
-- L6d · is there ANY currency name in the delivery? (columns whose name suggests one, over all 70 served columns)
-- ================================================================================================
SELECT count(*) AS served_columns, count(*) FILTER (WHERE lower(column_name) LIKE '%currency%') AS currency_columns, list(column_name) FILTER (WHERE lower(column_name) LIKE '%currency%') AS which FROM information_schema.columns WHERE table_schema='contoso_served';
-- ANSWER:
-- 70   3   ['FromCurrency', 'ToCurrency', 'CurrencyCode']

-- ================================================================================================
-- L6d2 · are those three columns codes or names? (value length and cardinality — a name would be longer than 3 characters)
-- ================================================================================================
SELECT (SELECT max(length("CurrencyCode")) FROM contoso_served.v_contoso_order_line) AS fact_code_len, (SELECT max(length("FromCurrency")) FROM contoso_served.v_contoso_fx_rate_day) AS fx_from_len, (SELECT max(length("ToCurrency")) FROM contoso_served.v_contoso_fx_rate_day) AS fx_to_len, (SELECT count(DISTINCT "CurrencyCode") FROM contoso_served.v_contoso_order_line) AS fact_codes;
-- ANSWER:
-- 3   3   3   5

-- ================================================================================================
-- L6e · does a product NAME resolve to one key? (search_key uniqueness on the product register's cut)
-- ================================================================================================
SELECT count(*) AS products, count(DISTINCT lower(trim("ProductName"))) AS distinct_search_keys, count(DISTINCT "ProductCode") AS distinct_codes, count(DISTINCT "ProductName") AS distinct_names FROM contoso_served.dim_contoso_product;
-- ANSWER:
-- 2517   2517   2517   2517

-- ================================================================================================
-- L6f · does a store DESCRIPTION resolve to one version?
-- ================================================================================================
SELECT count(*) AS store_versions, count(DISTINCT "Description") AS distinct_descriptions, count(DISTINCT lower(trim("Description"))) AS distinct_search_keys FROM contoso_served.dim_contoso_store;
-- ANSWER:
-- 74   67   67

-- ================================================================================================
-- L6g · the month register carries two search keys: on how many months do they coincide?
-- ================================================================================================
SELECT count(*) AS months, count(*) FILTER (WHERE lower("Month") = lower("MonthShort")) AS coinciding, list(DISTINCT "Month") FILTER (WHERE lower("Month") = lower("MonthShort")) AS which FROM (SELECT DISTINCT "MonthNumber", "Month", "MonthShort" FROM contoso_served.dim_contoso_calendar_day);
-- ANSWER:
-- 12   1   ['May']

-- ================================================================================================
-- L7a · the fact's CurrencyCode set vs the FX relation's From/To sets
-- ================================================================================================
SELECT (SELECT count(DISTINCT "CurrencyCode") FROM contoso_served.v_contoso_order_line) AS fact_codes, (SELECT count(DISTINCT "FromCurrency") FROM contoso_served.v_contoso_fx_rate_day) AS fx_from, (SELECT count(DISTINCT "ToCurrency") FROM contoso_served.v_contoso_fx_rate_day) AS fx_to, (SELECT count(*) FROM (SELECT DISTINCT "CurrencyCode" FROM contoso_served.v_contoso_order_line EXCEPT SELECT DISTINCT "FromCurrency" FROM contoso_served.v_contoso_fx_rate_day)) AS fact_not_in_fx, (SELECT count(*) FROM (SELECT DISTINCT "FromCurrency" FROM contoso_served.v_contoso_fx_rate_day EXCEPT SELECT DISTINCT "CurrencyCode" FROM contoso_served.v_contoso_order_line)) AS fx_not_in_fact;
-- ANSWER:
-- 5   5   5   0   0

-- ================================================================================================
-- L7b · customer `Country` vs store `CountryCode`: the same code system?
-- ================================================================================================
SELECT (SELECT count(*) FROM (SELECT DISTINCT "Country" FROM contoso_served.dim_contoso_customer EXCEPT SELECT DISTINCT "CountryCode" FROM contoso_served.dim_contoso_store)) AS customer_only, (SELECT count(*) FROM (SELECT DISTINCT "CountryCode" FROM contoso_served.dim_contoso_store EXCEPT SELECT DISTINCT "Country" FROM contoso_served.dim_contoso_customer)) AS store_only, (SELECT list(DISTINCT "CountryCode") FROM contoso_served.dim_contoso_store WHERE "CountryCode" NOT IN (SELECT "Country" FROM contoso_served.dim_contoso_customer)) AS which_store_only;
-- ANSWER:
-- 0   1   ['--']

-- ================================================================================================
-- L7c · do the two relations AGREE on the country name for a shared code?
-- ================================================================================================
SELECT count(*) AS shared_codes, count(*) FILTER (WHERE name_c = name_s) AS agreeing, count(*) FILTER (WHERE name_c <> name_s) AS disagreeing FROM (SELECT DISTINCT "Country" code, "CountryFull" name_c FROM contoso_served.dim_contoso_customer) c JOIN (SELECT DISTINCT "CountryCode" code, "CountryName" name_s FROM contoso_served.dim_contoso_store) s USING (code);
-- ANSWER:
-- 8   8   0

-- ================================================================================================
-- L8a · every served order line's ProductKey / StoreKey / CustomerKey resolves in a register (lines that do NOT)
-- ================================================================================================
SELECT count(*) AS lines, count(*) FILTER (WHERE p."ProductKey" IS NULL) AS product_unresolved, count(*) FILTER (WHERE s."StoreKey" IS NULL) AS store_unresolved, count(*) FILTER (WHERE c."CustomerKey" IS NULL) AS customer_row_missing FROM contoso_served.v_contoso_order_line f LEFT JOIN contoso_served.dim_contoso_product p USING ("ProductKey") LEFT JOIN contoso_served.dim_contoso_store s USING ("StoreKey") LEFT JOIN contoso_served.dim_contoso_customer c USING ("CustomerKey");
-- ANSWER:
-- 223974   0   0   0

-- ================================================================================================
-- L8b · every served product's Brand / CategoryKey / SubCategoryKey / Color / WeightUnit value appears in its register (values that do NOT — a register cut from the same relation must resolve all of it)
-- ================================================================================================
SELECT count(*) AS products, count(*) FILTER (WHERE "Brand" IS NULL) AS brand_null, count(*) FILTER (WHERE "CategoryKey" IS NULL) AS category_null, count(*) FILTER (WHERE "SubCategoryKey" IS NULL) AS subcategory_null, count(*) FILTER (WHERE "Color" IS NULL) AS color_null, count(*) FILTER (WHERE "WeightUnit" IS NULL) AS weightunit_null FROM contoso_served.dim_contoso_product;
-- ANSWER:
-- 2517   0   0   0   0   222

-- ================================================================================================
-- L8c · every served customer's Country and GeoAreaKey resolves; every served store's CountryCode resolves
-- ================================================================================================
SELECT (SELECT count(*) FROM contoso_served.dim_contoso_customer WHERE "Country" IS NULL OR "GeoAreaKey" IS NULL) AS customers_unresolvable, (SELECT count(*) FROM contoso_served.dim_contoso_store WHERE "CountryCode" IS NULL) AS stores_unresolvable, (SELECT count(*) FROM contoso_served.v_contoso_order_line WHERE "CurrencyCode" IS NULL) AS lines_without_currency;
-- ANSWER:
-- 0   0   0

-- ================================================================================================
-- L8d · every calendar day's MonthNumber / Quarter / DayofWeekNumber / WorkingDay is a registered value
-- ================================================================================================
SELECT count(*) AS days, count(*) FILTER (WHERE "MonthNumber" NOT BETWEEN 1 AND 12) AS month_out_of_register, count(*) FILTER (WHERE "Quarter" NOT IN ('Q1','Q2','Q3','Q4')) AS quarter_out_of_register, count(*) FILTER (WHERE "DayofWeekNumber" NOT BETWEEN 1 AND 7) AS weekday_out_of_register, count(*) FILTER (WHERE "WorkingDay" NOT IN (0, 1)) AS workingday_out_of_register FROM contoso_served.dim_contoso_calendar_day;
-- ANSWER:
-- 4018   0   0   0   0

-- ================================================================================================
-- L9a · Color: the landing's spellings vs the served register's rows
-- ================================================================================================
SELECT (SELECT count(DISTINCT "Color") FROM main.product) AS raw_spellings, (SELECT count(DISTINCT "Color") FROM contoso_served.dim_contoso_product) AS served_values, (SELECT list(DISTINCT "Color") FROM main.product WHERE "Color" NOT IN (SELECT "Color" FROM contoso_served.dim_contoso_product)) AS spellings_a_raw_cut_would_have_added;
-- ANSWER:
-- 17   16   ['blue']

-- ================================================================================================
-- L9b · WeightUnit and Status: '' in the landing vs NULL on the served side
-- ================================================================================================
SELECT (SELECT count(*) FROM main.product WHERE "WeightUnit" = '') AS raw_weightunit_empty, (SELECT count(*) FROM contoso_served.dim_contoso_product WHERE "WeightUnit" IS NULL) AS served_null, (SELECT count(DISTINCT "WeightUnit") FROM main.product) AS raw_weightunit_values, (SELECT count(DISTINCT "WeightUnit") FROM contoso_served.dim_contoso_product) AS served_values, (SELECT count(*) FROM main.store WHERE "Status" = '') AS raw_status_empty, (SELECT count(DISTINCT "Status") FROM main.store) AS raw_status_values, (SELECT count(DISTINCT "Status") FROM contoso_served.dim_contoso_store) AS served_status_values;
-- ANSWER:
-- 222   222   4   3   58   3   2

-- ================================================================================================
-- L9c · the region labels: padded spellings in the landing vs the served register
-- ================================================================================================
SELECT (SELECT count(DISTINCT "State") FROM main.customer) AS raw_abbreviations, (SELECT count(DISTINCT "State") FROM contoso_served.dim_contoso_customer) AS served_abbreviations, (SELECT count(DISTINCT "StateFull") FROM main.customer) AS raw_names, (SELECT count(DISTINCT "StateFull") FROM contoso_served.dim_contoso_customer) AS served_names, (SELECT count(*) FROM main.customer WHERE "State" <> trim("State") OR "StateFull" <> trim("StateFull")) AS raw_padded_rows;
-- ANSWER:
-- 565   563   610   608   4

-- ================================================================================================
-- L10 · WorkingDay: which value means a working day? (measured, not assumed)
-- ================================================================================================
SELECT count(*) FILTER (WHERE "DayofWeekNumber" IN (1, 7)) AS weekend_days, count(*) FILTER (WHERE "DayofWeekNumber" IN (1, 7) AND "WorkingDay" = 1) AS weekend_days_flagged_1, count(*) FILTER (WHERE "DayofWeekNumber" BETWEEN 2 AND 6 AND "WorkingDay" = 0) AS weekdays_flagged_0_holidays, count(*) FILTER (WHERE "WorkingDay" = 1) AS days_flagged_1, count(*) AS days FROM contoso_served.dim_contoso_calendar_day;
-- ANSWER:
-- 1148   0   110   2760   4018

-- ================================================================================================
-- L11 · the year-quarter code: does YearQuarterNumber = Year*4 + quarter hold on every day?
-- ================================================================================================
SELECT count(*) AS days, count(*) FILTER (WHERE "YearQuarterNumber" = "Year" * 4 + CAST(substr("Quarter", 2, 1) AS INTEGER)) AS days_matching_the_arithmetic FROM contoso_served.dim_contoso_calendar_day;
-- ANSWER:
-- 4018   4018

-- ================================================================================================
-- L12a · City: the cardinality and the ambiguity that refuse it a register
-- ================================================================================================
SELECT count(DISTINCT "City") AS city_names, count(DISTINCT ("City", "State", "Country")) AS city_state_country_triples, (SELECT count(*) FROM (SELECT "City" FROM contoso_served.dim_contoso_customer GROUP BY 1 HAVING count(DISTINCT ("State", "Country")) > 1)) AS city_names_in_2plus_regions, count(DISTINCT "ZipCode") AS zip_codes FROM contoso_served.dim_contoso_customer;
-- ANSWER:
-- 34581   39459   2642   40639

-- ================================================================================================
-- L12b · Customer: is there anything to resolve a customer BY? (served columns that could carry a customer name)
-- ================================================================================================
SELECT count(*) AS served_customer_columns, count(*) FILTER (WHERE lower(column_name) LIKE '%name%') AS name_columns, list(column_name) AS which FROM information_schema.columns WHERE table_schema='contoso_served' AND table_name='dim_contoso_customer';
-- ANSWER:
-- 12   0   ['CustomerKey', 'GeoAreaKey', 'StartDT', 'EndDT', 'Continent', 'CountryFull', 'Country', 'StateFull', 'State', 'City', 'ZipCode', 'Gender']

-- ================================================================================================
-- L12c · the period labels a register would duplicate: YearMonth / YearQuarter / Year cardinality on the calendar, and the fact's own span
-- ================================================================================================
SELECT (SELECT count(DISTINCT "YearMonth") FROM contoso_served.dim_contoso_calendar_day) AS year_months, (SELECT count(DISTINCT "YearQuarter") FROM contoso_served.dim_contoso_calendar_day) AS year_quarters, (SELECT count(DISTINCT "Year") FROM contoso_served.dim_contoso_calendar_day) AS years, (SELECT max("Date") FROM contoso_served.dim_contoso_calendar_day) AS calendar_last_day, (SELECT max("OrderDate") FROM contoso_served.v_contoso_order_line) AS fact_last_order_date;
-- ANSWER:
-- 132   44   11   2026-12-31 00:00:00   2025-12-31 00:00:00

-- ================================================================================================
-- L13 · shape of every register written, checked offline over the files themselves: header[0] is the code column (check_no_fabricated_identifiers reads header[0] as the register's key); the code column is spelled as EVERY source relation of its rows spells it; the code column is unique (one row per code); how many rows' search keys are distinct (a fold that is not 1:1 over-selects, so it may never be used as an identity); no `#` preamble above the header (a preamble makes csv.DictReader take the comment as the header and the lookup and measure-registry gates then tick over zero parsed rows); and no register accidentally carries the measure-registry columns, which are P8's registry and not this step's
-- ================================================================================================
